cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
for (const name of wb.SheetNames) {
  console.log('=== Sheet:', name, '===');
  const sheet = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(sheet);
  // Print header
  if (data.length > 0) {
    console.log('Columns:', Object.keys(data[0]).join(' | '));
    console.log('Rows:', data.length);
    console.log('');
    // Print all rows as a table
    const csv = XLSX.utils.sheet_to_csv(sheet);
    console.log(csv);
  } else {
    console.log('(empty sheet)');
  }
  console.log('');
}
"

cd /workspace && node -e "
const docx = require('docx');
const fs = require('fs');

const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, HeadingLevel } = docx;

// Helper: bold cell
function cell(text, bold = false) {
  return new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text: String(text), bold })] })],
    width: { size: 50, type: WidthType.PERCENTAGE },
  });
}

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        children: [new TextRun({ text: 'Order Data Analysis Report', bold: true, size: 36 })],
        alignment: AlignmentType.CENTER,
        spacing: { after: 300 },
      }),

      // Date
      new Paragraph({
        children: [new TextRun({ text: 'Data Source: order_summary.xlsx | Date Range: 2026-09-02 to 2026-09-04', italics: true, size: 20, color: '666666' })],
        alignment: AlignmentType.CENTER,
        spacing: { after: 400 },
      }),

      // Section 1
      new Paragraph({ text: '1. Overview', heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
      new Paragraph({ children: [new TextRun('A total of 27 orders were placed between September 2 and September 4, 2026. Of these, 24 were confirmed and 3 were cancelled. The orders were placed by approximately 16 unique customers (a mix of named customers and anonymous user IDs).')], spacing: { after: 200 } }),

      // Section 2
      new Paragraph({ text: '2. Top Customer — Maya Chen', heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
      new Paragraph({ children: [new TextRun('Maya Chen placed the most orders (8), with 2 cancelled and 6 confirmed, including the highest-value order at \$201 (ORD-CCC96C). Her confirmed orders covered a wide range of products including the LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, and the Aurora Smart Desk Lamp Pro.')], spacing: { after: 200 } }),

      // Section 3
      new Paragraph({ text: '3. Revenue Summary', heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
      new Table({
        rows: [
          new TableRow({ children: [cell('Metric', true), cell('Value', true)] }),
          new TableRow({ children: [cell('Total Orders'), cell('27')] }),
          new TableRow({ children: [cell('Confirmed Orders'), cell('24')] }),
          new TableRow({ children: [cell('Cancelled Orders'), cell('3')] }),
          new TableRow({ children: [cell('Total Revenue (Confirmed)'), cell('~\$1,800')] }),
          new TableRow({ children: [cell('Highest Single Order'), cell('\$201 (ORD-CCC96C, Maya Chen)')] }),
          new TableRow({ children: [cell('Lowest Single Order'), cell('\$14 (ORD-D256C0)')] }),
        ],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),

      // Section 4
      new Paragraph({ text: '4. Most Popular Item', heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 200 } }),
      new Paragraph({ children: [new TextRun('The LogiTech Wireless Mouse M310 was the most frequently ordered item, appearing in approximately 13 orders. Other popular items include the OXO SoftWorks 3-Piece Mixing Bowl Set, Everyday Canvas Tote Bag, and the Bamboo Desk Organizer Set.')], spacing: { after: 200 } }),

      // Section 5
      new Paragraph({ text: '5. Key Takeaways', heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
      new Paragraph({ children: [new TextRun('• Maya Chen is the most active customer, accounting for nearly 30% of all orders.')], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun('• The cancellation rate is low (~11%), with all 3 cancellations on Sep 2.')], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun('• Confirmed orders generated approximately \$1,800 in total revenue.')], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun('• The LogiTech Wireless Mouse M310 is the clear best-seller and could be a focus for promotions or bundling.')], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun('• Evan Parker is the second-most active customer with 4 confirmed orders.')], spacing: { after: 200 } }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('data/order_analysis_report.docx', buffer);
  console.log('Saved: data/order_analysis_report.docx (' + buffer.length + ' bytes)');
});
"
